  });
});

it('maps listFor failures to safe errors and logs only non-sensitive diagnostics', async () => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const {setLogger} = await import('../../shared/logger.js');
  const logged: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
  setLogger({
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: (category, message, fields) => logged.push({category, message, fields}),
  });
  try {
    const listFor = jest
      .fn<NonNullable<SessionStore['listFor']>>()
      .mockRejectedValueOnce(new Error('database password=secret'))
      .mockRejectedValueOnce(new StoreCannotList());
    const sessionStore = {listFor} as unknown as SessionStore;
    const handle = createMessageHandler({} as ChatOrchestrator, {sessionStore, history: {enabled: true}});

    await handle(ws, session, {type: 'list_conversations'});
    await handle(ws, session, {type: 'list_conversations'});
  } finally {
    setLogger();
  }

  expect(sent).toEqual([
    {type: 'error', code: 'SERVER_ERROR', message: 'Could not list conversations'},
    {type: 'error', code: 'UNSUPPORTED', message: 'This session store cannot list conversations'},
  ]);
  expect(logged).toEqual([
    {
      category: 'message',
      message: 'conversation list failed',
      fields: {sessionId: 's1', userId: 'u1', errorType: 'Error'},
    },
    {
      category: 'message',
      message: 'conversation list failed',
      fields: {sessionId: 's1', userId: 'u1', errorType: 'StoreCannotList'},
    },
  ]);
});

// One real turn through the handler: the model asks for `call` and, handed its result, answers.
async function turnOver(call: ToolCall, registry: ToolRegistry): Promise<string[]> {
  let requests = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      requests++;
      const asks: MessageChunk[] = [
        {type: 'tool_use', toolCall: call},
        {type: 'stop', stopReason: 'tool_use'},
      ];
      yield* requests === 1 ? asks : [text('all done'), STOP];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Failure test.'}), registry);
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  await createMessageHandler(orchestrator)(ws, session, userMessage('hello'));
  return wire(sent);
}

// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}
